Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background: #000; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- SCENE SETUP ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- LIGHTING ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 100;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        scene.add(dirLight);

        // --- ENVIRONMENT ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(200, 200);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a7d44, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(20, 200);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.01;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishLineGroup = new THREE.Group();
        // Create a simple checkered pattern using canvas texture
        const canvas = document.createElement('canvas');
        canvas.width = 256;
        canvas.height = 256;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0, 0, 256, 256);
        ctx.fillStyle = 'black';
        for(let y=0; y<8; y++) {
            for(let x=0; x<8; x++) {
                if((x+y)%2 === 0) {
                    ctx.fillRect(x*32, y*32, 32, 32);
                }
            }
        }
        const texture = new THREE.CanvasTexture(canvas);
        const finishGeo = new THREE.PlaneGeometry(10, 2);
        const finishMat = new THREE.MeshStandardMaterial({ map: texture });
        const finishPlane = new THREE.Mesh(finishGeo, finishMat);
        finishPlane.rotation.x = -Math.PI / 2;
        finishPlane.position.y = 0.02;
        finishLineGroup.add(finishPlane);

        // Finish Line Posts
        const postGeo = new THREE.CylinderGeometry(0.2, 0.2, 4);
        const postMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const leftPost = new THREE.Mesh(postGeo, postMat);
        leftPost.position.set(-5, 2, 0);
        const rightPost = new THREE.Mesh(postGeo, postMat);
        rightPost.position.set(5, 2, 0);
        finishLineGroup.add(leftPost, rightPost);

        // Banner
        const bannerGeo = new THREE.BoxGeometry(10, 1, 0.5);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 4, 0);
        finishLineGroup.add(banner);

        finishLineGroup.position.z = 50; // Finish line is at z=50
        scene.add(finishLineGroup);

        // --- CAR FACTORY ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2.2, 1, 4);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.2 });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.7;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.8, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.1 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.6;
            cabin.position.z = -0.2;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
            const wheelPositions = [
                { x: -1.2, y: 0.4, z: 1.2 },
                { x: 1.2, y: 0.4, z: 1.2 },
                { x: -1.2, y: 0.4, z: -1.2 },
                { x: 1.2, y: 0.4, z: -1.2 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, pos.y, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Headlights
            const lightGeo = new THREE.SphereGeometry(0.2, 16, 16);
            const lightMat = new THREE.MeshStandardMaterial({ color: 0xffffaa, emissive: 0xffffaa });
            const leftLight = new THREE.Mesh(lightGeo, lightMat);
            leftLight.position.set(-0.8, 0.9, -2);
            const rightLight = new THREE.Mesh(lightGeo, lightMat);
            rightLight.position.set(0.8, 0.9, -2);
            carGroup.add(leftLight, rightLight);

            return carGroup;
        }

        // --- CREATE CARS ---
        const redCar = createCar(0xff0000);
        redCar.position.set(-4, 0, -50); // Start at z=-50
        scene.add(redCar);

        const blueCar = createCar(0x0000ff);
        blueCar.position.set(4, 0, -50);
        scene.add(blueCar);

        // --- ANIMATION STATE ---
        let raceTime = 0;
        const finishLineZ = 50;
        const startZ = -50;
        const raceDistance = 100;

        // Animation parameters
        // Blue car: Fast start, then slows down
        // Red car: Slow start, then accelerates
        // Total race duration approx 4 seconds

        function updateCars(dt) {
            // Normalize time from 0 to 1 for the race loop
            // We'll use a custom time curve for better visual pacing

            const duration = 4.0; // seconds for one race
            const cycleTime = raceTime % duration;

            // Calculate progress 0.0 to 1.0
            let progress = cycleTime / duration;

            // Blue Car Animation:
            // Starts fast, reaches finish, then resets
            // We want blue to finish first, so we map its progress differently or just animate it independently
            // Let's make them independent to allow the "overtake" logic to be visual

            // Blue Car: Fast start, decelerates
            // Blue reaches z=50 at t=2.0s
            const blueSpeedCurve = (t) => {
                if (t < 2.0) {
                    // Fast start
                    return t * 25; // Speed decreases? No, let's just use position curves
                }
                return 50;
            };

            // Let's define position directly based on time for smoother control
            // Red Car: Accelerates
            // Blue Car: Constant then stops

            // Reset logic:
            // At t=4.0, everything resets.

            // Blue Car:
            // t=0: z=-50
            // t=1.5: z=50 (Fast)
            // t=4.0: z=-50 (Teleport reset)
            let blueZ;
            if (cycleTime < 1.5) {
                blueZ = -50 + (cycleTime / 1.5) * 100;
            } else if (cycleTime < 4.0) {
                blueZ = 50; // Wait at finish
            } else {
                // Reset phase
                const resetProgress = (cycleTime - 4.0) / 1.0; // 1 second reset
                blueZ = 50 - (resetProgress * 100);
            }

            // Red Car:
            // t=0: z=-50
            // t=2.0: z=50 (Slower start, faster end)
            // t=4.0: z=-50
            let redZ;
            if (cycleTime < 2.0) {
                // Accelerate
                redZ = -50 + (Math.pow(cycleTime / 2.0, 1.5)) * 100;
            } else if (cycleTime < 4.0) {
                redZ = 50; // Wait at finish
            } else {
                const resetProgress = (cycleTime - 4.0) / 1.0;
                redZ = 50 - (resetProgress * 100);
            }

            // Update positions
            redCar.position.z = redZ;
            blueCar.position.z = blueZ;

            // Add slight bounce
            redCar.position.y = Math.sin(cycleTime * 10) * 0.05;
            blueCar.position.y = Math.sin(cycleTime * 12) * 0.05;

            // Rotate wheels slightly for effect
            redCar.children.forEach(child => {
                if(child.geometry && child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x += 0.1;
                }
            });
            blueCar.children.forEach(child => {
                if(child.geometry && child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x += 0.1;
                }
            });
        }

        // --- CAMERA ---
        const cameraOffset = new THREE.Vector3(0, 8, 15);

        function updateCamera() {
            // Find the average position of the two cars
            const avgZ = (redCar.position.z + blueCar.position.z) / 2;
            const avgX = (redCar.position.x + blueCar.position.x) / 2;

            // Smoothly interpolate camera position
            const targetZ = avgZ + 20; // Look ahead
            const targetX = avgX;

            camera.position.z += (targetZ - camera.position.z) * 0.05;
            camera.position.x += (targetX - camera.position.x) * 0.05;
            camera.position.y += (8 - camera.position.y) * 0.05;

            camera.lookAt(avgX, 0, avgZ + 10);
        }

        // --- MAIN LOOP ---
        const clock = new THREE.Clock();

        function animate() {
            requestAnimationFrame(animate);

            const dt = clock.getDelta();
            raceTime += dt;

            updateCars(dt);
            updateCamera();

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
